const CACHE = 'pap-' + VERSION;
const AUDIO_CACHE = 'pap-audio';

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k !== CACHE && k !== AUDIO_CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

// la page demande le téléchargement des audios une fois chargée (par petits paquets, en arrière-plan)
self.addEventListener('message', e => {
  if (e.data !== 'precache-audio') return;
  e.waitUntil((async () => {
    const c = await caches.open(AUDIO_CACHE);
    const have = new Set((await c.keys()).map(r => new URL(r.url).pathname.split('/').pop()));
    const keep = new Set(AUDIO.map(a => a.split('/').pop()));
    for (const r of await c.keys()) if (!keep.has(new URL(r.url).pathname.split('/').pop())) await c.delete(r);
    const todo = AUDIO.filter(a => !have.has(a.split('/').pop()));
    for (let i = 0; i < todo.length; i += 20) {
      await Promise.all(todo.slice(i, i + 20).map(u => fetch(u).then(r => r.ok && c.put(u, r)).catch(() => { })));
    }
  })());
});

self.addEventListener('fetch', e => {
  const url = new URL(e.request.url);
  if (e.request.method !== 'GET' || url.origin !== location.origin) return;
  const isAudio = url.pathname.includes('/audio/');
  e.respondWith((async () => {
    const hit = await caches.match(e.request, { ignoreSearch: true });
    if (hit) return hit;
    try {
      const r = await fetch(e.request);
      if (r.ok) (await caches.open(isAudio ? AUDIO_CACHE : CACHE)).put(e.request, r.clone());
      return r;
    } catch (err) {
      if (e.request.mode === 'navigate') return caches.match('index.html');
      throw err;
    }
  })());
});
